// TH18 st01mbs MBoss, MBoss1 and MBoss1_at. Controller owns phase, boss owns motion.
const TIME_LIMIT: int = 1322;
const TH18_RICE: int = 480;

xformdef RICE_MOTION(speed: fx, offset: angle, gain: fx, spin: angle) {
    @30 step_speed(0fx, 30);
    set_angle(at_effect(atan2($player_y-$self_y, $player_x-$self_x)+offset));
    set_speed(speed);
    set_ang_vel(spin);
    @100 set_accel(gain);
    set_ang_vel(0deg);
    set_accel(0fx);
}
sub volley(base: angle, offset: angle, spin: angle, n: int, layers: int, speed: fx) {
    for j in 0..layers {
        var gain: fx = (0.5fx+(j as fx)*0.35fx)/100;
        sh_reset(0);
        sh_sprite(0, TH18_RICE, 14);
        sh_ring(0, 1);
        sh_count(0, n, 1);
        sh_angle(0, base, 0deg);
        sh_speed(0, speed, 0fx);
        sh_dist(0, -4fx*speed);
        sh_xform(0, RICE_MOTION(speed, offset, gain, spin));
        sh_fire(0);
    }
}
async sub boss() {
    set_invuln(65535);
    set_hitbox(20fx);
    set_hurtbox(24fx);
    set_self_int(1, $frame+1200);
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    var rank: int = global(GVAR_RANK);
    var n: int = 16;
    var layers: int = 4;
    var delay: int = 110;
    var speed: fx = 2.5fx;
    if rank == 1 { layers = 7; }
    if rank == 2 { n = 20; layers = 9; delay = 80; speed = 3.5fx; }
    if rank == 3 { n = 24; layers = 9; delay = 60; speed = 4.5fx; }
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    loop {
        if $frame >= self_int(1) { return; }
        volley(90deg, 60deg, (237 as angle), n, layers, speed);
        card_wait(delay);
        if $frame >= self_int(1) { return; }
        volley(aim_player(), -60deg, (-237 as angle), n, layers, speed);
        card_move_rand();
        card_wait(delay);
    }
}
async sub pattern() {
    wait(120);
    _ = spawn_enemy(-192fx, -64fx, 7000, 0, 0, 0, boss);
    wait(1201);
}
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, controller);
    loop { wait(600); }
}

// TH18 v1.00a MBoss1. int slot0=next-step count, int1=source end card-frame; fx0/1=logical unit vector.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);

        card_arm_next_step();
    }
}
